pub async fn dispatch<S: ProtocolServer + ?Sized>(server: &S, request: ProtocolRequest) -> ProtocolResponse {
    match request {
        ProtocolRequest::ProtocolHandshake { protocol_version, id, params } => {
            let response = match server.protocol_handshake(params).await {
                Ok(result) => ResponsePayload::Ok { result },
                Err(error) => ResponsePayload::Error { error },
            };
            ProtocolResponse::ProtocolHandshake { protocol_version, id, response }
        },
        ProtocolRequest::EventSubscribe { protocol_version, id, params } => {
            let response = match server.event_subscribe(params).await {
                Ok(result) => ResponsePayload::Ok { result },
                Err(error) => ResponsePayload::Error { error },
            };
            ProtocolResponse::EventSubscribe { protocol_version, id, response }
        },
        ProtocolRequest::DeviceList { protocol_version, id, params } => {
            let response = match server.device_list(params).await {
                Ok(result) => ResponsePayload::Ok { result },
                Err(error) => ResponsePayload::Error { error },
            };
            ProtocolResponse::DeviceList { protocol_version, id, response }
        },
        ProtocolRequest::ProviderList { protocol_version, id, params } => {
            let response = match server.provider_list(params).await {
                Ok(result) => ResponsePayload::Ok { result },
                Err(error) => ResponsePayload::Error { error },
            };
            ProtocolResponse::ProviderList { protocol_version, id, response }
        },
        ProtocolRequest::ConversationList { protocol_version, id, params } => {
            let response = match server.conversation_list(params).await {
                Ok(result) => ResponsePayload::Ok { result },
                Err(error) => ResponsePayload::Error { error },
            };
            ProtocolResponse::ConversationList { protocol_version, id, response }
        },
        ProtocolRequest::ConversationSearch { protocol_version, id, params } => {
            let response = match server.conversation_search(params).await {
                Ok(result) => ResponsePayload::Ok { result },
                Err(error) => ResponsePayload::Error { error },
            };
            ProtocolResponse::ConversationSearch { protocol_version, id, response }
        },
        ProtocolRequest::ConversationGet { protocol_version, id, params } => {
            let response = match server.conversation_get(params).await {
                Ok(result) => ResponsePayload::Ok { result },
                Err(error) => ResponsePayload::Error { error },
            };
            ProtocolResponse::ConversationGet { protocol_version, id, response }
        },
        ProtocolRequest::ConversationCreate { protocol_version, id, params } => {
            let response = match server.conversation_create(params).await {
                Ok(result) => ResponsePayload::Ok { result },
                Err(error) => ResponsePayload::Error { error },
            };
            ProtocolResponse::ConversationCreate { protocol_version, id, response }
        },
        ProtocolRequest::TurnSend { protocol_version, id, params } => {
            let response = match server.turn_send(params).await {
                Ok(result) => ResponsePayload::Ok { result },
                Err(error) => ResponsePayload::Error { error },
            };
            ProtocolResponse::TurnSend { protocol_version, id, response }
        },
        ProtocolRequest::TurnInterrupt { protocol_version, id, params } => {
            let response = match server.turn_interrupt(params).await {
                Ok(result) => ResponsePayload::Ok { result },
                Err(error) => ResponsePayload::Error { error },
            };
            ProtocolResponse::TurnInterrupt { protocol_version, id, response }
        },
        ProtocolRequest::ApprovalResolve { protocol_version, id, params } => {
            let response = match server.approval_resolve(params).await {
                Ok(result) => ResponsePayload::Ok { result },
                Err(error) => ResponsePayload::Error { error },
            };
            ProtocolResponse::ApprovalResolve { protocol_version, id, response }
        }
    }
}

